 w.eval(fs.readFileSync('dist/app.js','utf8'));await wait(30);if(!options.restore){d.querySelector('#open').click();await until(()=>d.querySelector('#title').textContent==='A');}else await until(()=>d.querySelector('#title').textContent||d.querySelector('.active-pane .tool-view'));
