test('tab navigation preserves text and selection; leaving a note saves its edits',async t=>{let confirms=0;const h=await harness(t,{confirm:()=>{confirms++;return false;}});h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'My draft'},selection:{anchor:3}});h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#title').textContent==='B');await until(()=>h.saved.length===1);h.command('navigate-back');await until(()=>h.d.querySelector('#title').textContent==='A');assert.equal(h.view().state.doc.toString(),'My draft');assert.equal(h.view().state.selection.main.head,3);assert.equal(confirms,0);assert.equal(h.d.querySelectorAll('#tabs .tab').length,1);});
test('typing autosaves after a pause without clicking Save',async t=>{const h=await harness(t);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'First'}});await wait(100);h.view().dispatch({changes:{from:0,to:5,insert:'Latest'}});await until(()=>h.saved.length===1);assert.equal(h.saved[0].text,'Latest');assert.match(h.d.querySelector('#status').textContent,/Saved automatically/);assert.equal(h.d.querySelectorAll('.dirty-mark').length,0);});
test('edits made during a save are saved again in order',async t=>{let finish;let calls=0;const h=await harness(t,{write:async(p,text,saved)=>{calls++;saved.push({path:p,text});if(calls===1)await new Promise(r=>finish=r);const note=h.notes.find(n=>n.path===p);note.text=text;note.version=String(calls+1);return {...note};}});h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'First'}});await until(()=>calls===1);h.view().dispatch({changes:{from:0,to:5,insert:'Second'}});finish();await until(()=>calls===2);assert.deepEqual(h.saved.map(s=>s.text),['First','Second']);});
test('a failed autosave preserves edits and prevents accidental quit',async t=>{const h=await harness(t,{confirm:()=>false,write:async()=>{throw new Error('EACCES: Permission denied');}});h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Keep me'}});await until(()=>h.d.querySelector('.dirty-mark')?.textContent==='!');h.command('quit');await wait(50);assert.equal(h.closed(),false);assert.equal(h.view().state.doc.toString(),'Keep me');assert.match(h.d.querySelector('#status').textContent,/EACCES/);});
test('restore opens saved tabs; quick switcher supports Enter; preview sanitizes HTML',async t=>{const h=await harness(t,{restore:{tabs:['A.md','B.md'],active:'B.md',reading:false}});assert.equal(h.d.querySelectorAll('#tabs .tab').length,2);assert.equal(h.d.querySelector('#title').textContent,'B');h.command('switcher');await until(()=>h.d.querySelector('#switch-dialog').open);const input=h.d.querySelector('#switch-query');input.value='A';input.dispatchEvent(new h.w.Event('input'));input.dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));await until(()=>h.d.querySelector('#title').textContent==='A');await until(()=>!h.d.querySelector('#preview-button').disabled);h.d.querySelector('#preview-button').click();assert.equal(h.w.hacked,undefined);assert.equal(h.d.querySelectorAll('#reading script').length,0);assert.equal(h.d.querySelector('#reading a').textContent,'Go to B');await until(()=>h.workspaces.some(s=>s.active==='A.md'));});
test('external changes refresh clean tabs automatically without a Reload click',async t=>{const h=await harness(t);h.notes[0].text='External content';h.notes[0].version='2';await until(()=>h.view().state.doc.toString()==='External content');assert.match(h.d.querySelector('#status').textContent,/Updated from disk/);assert.equal(h.saved.length,0);});
test('external loads replace pending edits and cancel their autosave',async t=>{const h=await harness(t);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Local pending edit'}});h.notes[0].text='External content';h.notes[0].version='2';h.w.dispatchEvent(new h.w.Event('focus'));await until(()=>h.view().state.doc.toString()==='External content');assert.equal(h.d.querySelectorAll('.dirty-mark').length,0);await wait(700);assert.equal(h.saved.length,0);});
test('filesystem notifications refresh clean notes without waiting for the polling interval',async t=>{const h=await harness(t);h.notes[0].text='Instant external change';h.notes[0].version='2';h.changed();await until(()=>h.view().state.doc.toString()==='Instant external change');assert.equal(h.saved.length,0);});
test('Live Preview renders Markdown without changing source and reveals selected syntax',async t=>{const text='# Heading\n\n**Bold** and *italic* and ~~gone~~ and `code`\n\n[[B|Linked note]]\n\nEnd';const h=await harness(t,{text});h.view().dispatch({selection:{anchor:text.length}});assert.ok(h.d.querySelector('.cm-live-h1'));assert.ok(h.d.querySelector('.cm-live-strong'));assert.ok(h.d.querySelector('.cm-live-emphasis'));assert.ok(h.d.querySelector('.cm-live-strike'));assert.ok(h.d.querySelector('.cm-live-inline-code'));assert.equal(h.view().state.doc.toString(),text);assert.equal(h.d.querySelector('.cm-content').textContent.includes('**Bold**'),false);assert.equal(h.d.querySelector('.cm-live-link').textContent,'Linked note');h.view().dispatch({selection:{anchor:text.indexOf('Bold')+1}});assert.ok(h.d.querySelector('.cm-content').textContent.includes('**Bold**'));h.d.querySelector('#source-mode').click();assert.ok(h.d.querySelector('.cm-content').textContent.includes('[[B|Linked note]]'));assert.ok(h.d.querySelector('.cm-source-mode'));assert.equal(h.view().state.doc.toString(),text);await wait(700);assert.equal(h.saved.length,0);});
test('rendered task checkbox changes the Markdown and autosaves',async t=>{const text='Intro\n\n- [ ] Finish this\n\nEnd';const h=await harness(t,{text});const checkbox=h.d.querySelector('.cm-live-checkbox');assert.ok(checkbox);checkbox.checked=true;checkbox.dispatchEvent(new h.w.Event('change',{bubbles:true}));await until(()=>h.view().state.doc.toString().includes('- [x] Finish this'));await until(()=>h.saved.length===1);assert.ok(h.saved[0].text.includes('- [x] Finish this'));});
test('rendered table cells remain editable and write only their original source range',async t=>{const text='Intro\n\n| Name | Value |\n| --- | --- |\n| First | Old |\n| Second | Keep |\n\nEnd';const h=await harness(t,{text});await until(()=>h.d.querySelectorAll('.cm-live-table td').length===4);const cell=h.d.querySelectorAll('.cm-live-table td')[1];cell.click();let input=cell.querySelector('input');assert.ok(input);input.value='New';input.dispatchEvent(new h.w.Event('input',{bubbles:true}));assert.equal(h.view().state.doc.toString(),text.replace(' Old ',' New '));assert.ok(cell.querySelector('input'));input=cell.querySelector('input');input.value='New value';input.dispatchEvent(new h.w.Event('input',{bubbles:true}));assert.equal(h.view().state.doc.toString(),text.replace(' Old ',' New value '));await until(()=>h.saved.length===1);assert.ok(h.saved[0].text.includes('| Second | Keep |'));});
test('empty table cells and escaped pipes are editable without breaking columns',async t=>{const text='Intro\n\n| A | B |\n| --- | --- |\n|  | old |\n\nEnd';const h=await harness(t,{text});await until(()=>h.d.querySelectorAll('.cm-live-table td').length===2);const cell=h.d.querySelector('.cm-live-table td');cell.click();const input=cell.querySelector('input');input.value='one|two';input.dispatchEvent(new h.w.Event('input',{bubbles:true}));assert.ok(h.view().state.doc.toString().includes('one\\|two'));assert.equal(cell.querySelector('input').value,'one|two');assert.equal(h.d.querySelectorAll('.cm-live-table td').length,2);await until(()=>h.saved.length===1);});
test('code keeps literal Markdown and HTML-like text is never executed',async t=>{const text='Intro\n\n```md\n**Literal** [[B]] <script>window.hacked=true</script>\n```\n\n`[[B]]`\n\nEnd';const h=await harness(t,{text});assert.equal(h.d.querySelector('.cm-content').textContent.includes('**Literal** [[B]]'),true);assert.equal(h.d.querySelectorAll('.cm-content .cm-live-link').length,0);assert.equal(h.w.hacked,undefined);assert.equal(h.view().state.doc.toString(),text);});
test('switching Source and Live Preview keeps undo history and persists the editing mode',async t=>{const h=await harness(t,{restore:{tabs:['A.md'],active:'A.md',reading:false,editingMode:'source'}});assert.ok(h.d.querySelector('.cm-source-mode'));const original=h.view().state.doc.toString();h.view().dispatch({changes:{from:0,to:0,insert:'Added '}});h.d.querySelector('#source-mode').click();assert.ok(h.d.querySelector('.cm-live-preview'));const content=h.d.querySelector('.cm-content');content.dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'z',code:'KeyZ',ctrlKey:true,bubbles:true,cancelable:true}));assert.equal(h.view().state.doc.toString(),original);await until(()=>h.workspaces.some(s=>s.editingMode==='live'));});
test('plain click follows a live wiki link; Alt-click edits and Ctrl-click opens a new tab',async t=>{const text='Intro\n\n[[B|Go there]]\n\nEnd';const h=await harness(t,{text});let link=h.d.querySelector('.cm-live-link');link.dispatchEvent(new h.w.MouseEvent('click',{altKey:true,bubbles:true,cancelable:true}));assert.equal(h.d.querySelector('.cm-content').textContent.includes('[[B|Go there]]'),true);h.view().dispatch({selection:{anchor:0}});link=h.d.querySelector('.cm-live-link');link.dispatchEvent(new h.w.MouseEvent('click',{ctrlKey:true,bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('#title').textContent==='B');assert.equal(h.d.querySelectorAll('#tabs .tab').length,2);});

function aiMock(overrides={}){let chunk;const requests=[],chats=new Map();return {requests,settings:async()=>({active:'api',secureKeys:true,providers:[{id:'api',name:'Test Gateway',type:'openai',url:'https://host/v1',model:'test',hasKey:true}],detected:[]}),save:async value=>({...value,secureKeys:true,detected:[]}),thread:async p=>chats.get(p)||[],clear:async p=>chats.delete(p),cancel:async()=>{},emit:event=>chunk(event),onChunk:cb=>chunk=cb,chat:async request=>{requests.push(request);chunk({id:request.id,text:'**Answer** <script>window.hacked=true</script>'});const thread=[...request.history,{role:'user',content:request.prompt,context:request.context.map(n=>n.path)},{role:'assistant',content:'**Answer** <script>window.hacked=true</script>',provider:'Test Gateway'}];chats.set(request.context[0].path,thread);return {thread,content:thread.at(-1).content};},...overrides};}
test('AI chat sends unsaved current text and an explicitly mentioned note, sanitizes replies and preserves per-note history',async t=>{const ai=aiMock(),h=await harness(t,{ai});await until(()=>!h.d.querySelector('#chat-send').disabled);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Unsaved idea'}});const input=h.d.querySelector('#chat-input');input.value='Compare @B';input.selectionStart=input.value.length;input.dispatchEvent(new h.w.Event('input'));assert.equal(h.d.querySelector('#mention-results').hidden,false);h.d.querySelector('#mention-results button').click();assert.match(input.value,/@\[\[B.md\]\]/);assert.equal(h.d.querySelectorAll('.context-chip').length,2);h.d.querySelector('#chat-send').click();await until(()=>ai.requests.length===1);await wait(50);assert.equal(h.d.querySelector('#chat-status').textContent,'Response complete.');assert.equal(ai.requests[0].context[0].text,'Unsaved idea');assert.equal(ai.requests[0].context[1].path,'B.md');assert.equal(ai.requests[0].context[1].text,undefined);assert.equal(h.w.hacked,undefined);assert.equal(h.d.querySelectorAll('#chat-messages script').length,0);assert.ok(h.d.querySelector('#chat-messages strong'));h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#chat-note').textContent==='B.md');assert.equal(h.d.querySelectorAll('.chat-message').length,0);h.command('navigate-back');await until(()=>h.d.querySelector('#chat-note').textContent==='A.md');assert.equal(h.d.querySelectorAll('.chat-message').length,2);});
test('AI failures retain the prompt for retry and never modify the note',async t=>{const ai=aiMock({chat:async()=>{throw new Error('Gateway offline');}}),h=await harness(t,{ai});await until(()=>!h.d.querySelector('#chat-send').disabled);const original=h.view().state.doc.toString();h.d.querySelector('#chat-input').value='Explain';h.d.querySelector('#chat-send').click();await until(()=>h.d.querySelector('#chat-status').textContent==='Gateway offline');assert.equal(h.d.querySelector('#chat-input').value,'Explain');assert.equal(h.view().state.doc.toString(),original);assert.equal(h.saved.length,0);assert.equal(h.d.querySelector('#chat-send').disabled,false);});
test('AI Settings saves model, custom gateway URL and a replacement key, then clears the password field',async t=>{let saved;const ai=aiMock({save:async value=>{saved=value;return {...value,secureKeys:true,detected:[]};}}),h=await harness(t,{ai});h.d.querySelector('#settings').click();h.d.querySelector('#settings-nav-ai').click();h.d.querySelector('#settings-ai-open').click();await until(()=>h.d.querySelector('#settings-dialog').open);h.d.querySelector('#provider-url').value='https://gateway.example/v1';h.d.querySelector('#provider-model').value='my-deployment';h.d.querySelector('#provider-key').value='new-key';h.d.querySelector('#settings-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>!h.d.querySelector('#settings-dialog').open);assert.equal(saved.providers[0].url,'https://gateway.example/v1');assert.equal(saved.providers[0].model,'my-deployment');assert.equal(saved.providers[0].key,'new-key');assert.equal(h.d.querySelector('#provider-key').value,'');});
test('a response remains attached to its originating note when switching tabs',async t=>{let finish;const ai=aiMock({chat:request=>new Promise(resolve=>{finish=()=>resolve({thread:[{role:'user',content:request.prompt},{role:'assistant',content:'Only A answer'}],content:'Only A answer'});})}),h=await harness(t,{ai});await until(()=>!h.d.querySelector('#chat-send').disabled);h.d.querySelector('#chat-input').value='Question for A';h.d.querySelector('#chat-send').click();await until(()=>finish);h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#chat-note').textContent==='B.md');finish();await until(()=>h.d.querySelector('#chat-send').disabled===false);assert.doesNotMatch(h.d.querySelector('#chat-messages').textContent,/Only A answer/);h.command('navigate-back');await until(()=>h.d.querySelector('#chat-note').textContent==='A.md');assert.match(h.d.querySelector('#chat-messages').textContent,/Only A answer/);});

test('explorer and chat collapse independently, preserve drafts and persist their state',async t=>{const ai=aiMock(),h=await harness(t,{ai});await until(()=>!h.d.querySelector('#chat-input').disabled);const doc=h.view().state.doc.toString();const input=h.d.querySelector('#chat-input');input.value='Keep this draft';input.dispatchEvent(new h.w.Event('input'));h.d.querySelector('#left-toggle').click();assert.equal(h.d.querySelector('#explorer').hidden,true);assert.equal(h.d.querySelector('#right-sidebar').hidden,false);assert.equal(h.d.querySelector('#left-toggle').getAttribute('aria-expanded'),'false');assert.ok(h.d.querySelector('.ribbon #settings'));h.d.querySelector('#ai-toggle').click();assert.equal(h.d.querySelector('#right-sidebar').hidden,true);h.d.querySelector('#ai-toggle').click();assert.equal(input.value,'Keep this draft');assert.equal(h.view().state.doc.toString(),doc);await until(()=>h.workspaces.some(v=>v.layout.leftOpen===false&&v.layout.rightOpen===true));h.command('search');await until(()=>h.d.querySelector('#explorer').hidden===false);assert.equal(h.d.activeElement.id,'search');});
test('workspace restores sidebar widths, collapsed panels and the backlinks pane',async t=>{const h=await harness(t,{restore:{tabs:['A.md'],active:'A.md',layout:{leftOpen:false,rightOpen:true,leftWidth:200,rightWidth:300,rightPane:'links',collapsedFolders:[]}}});assert.equal(h.d.querySelector('#explorer').hidden,true);assert.equal(h.d.querySelector('#chat-panel').hidden,true);assert.equal(h.d.querySelector('#links-panel').hidden,false);assert.equal(h.d.querySelector('main').style.getPropertyValue('--right-width'),'300px');h.d.querySelector('#left-toggle').click();const handle=h.d.querySelector('#left-resize');handle.dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true,cancelable:true}));assert.equal(handle.getAttribute('aria-valuenow'),'220');await until(()=>h.workspaces.some(v=>v.layout.leftWidth===220));});
test('sidebar resize clamps widths and supports pointer dragging without changing note contents',async t=>{const h=await harness(t),handle=h.d.querySelector('#right-resize');const original=h.view().state.doc.toString();handle.dispatchEvent(new h.w.MouseEvent('pointerdown',{button:0,clientX:100,bubbles:true}));handle.dispatchEvent(new h.w.MouseEvent('pointermove',{clientX:50,bubbles:true}));handle.dispatchEvent(new h.w.MouseEvent('pointerup',{clientX:50,bubbles:true}));await until(()=>h.workspaces.some(v=>v.layout.rightWidth===390));handle.dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'Home',bubbles:true}));assert.equal(handle.getAttribute('aria-valuenow'),'280');assert.equal(h.view().state.doc.toString(),original);assert.equal(h.saved.length,0);});
test('folder explorer groups paths, remembers collapse and exposes quiet accessible controls',async t=>{const h=await harness(t,{extraNotes:[{path:'Ideas/Nested.md',title:'Nested',text:'Idea',version:'1'}]});const folder=h.d.querySelector('.folder');assert.equal(folder.querySelector('summary span').textContent,'Ideas');assert.equal(folder.querySelector('.file-item').title,'Ideas/Nested.md');folder.open=false;folder.dispatchEvent(new h.w.Event('toggle'));await until(()=>h.workspaces.some(v=>v.layout.collapsedFolders.includes('Ideas')));h.changed();await wait(60);assert.equal(h.d.querySelector('.folder').open,false);assert.equal(h.d.querySelector('#settings').getAttribute('aria-label'),'Settings (Cmd/Ctrl+,)');assert.ok(h.d.querySelector('#settings svg'));const menu=h.d.querySelector('#note-menu');menu.open=true;h.d.querySelector('#source-mode').click();assert.equal(menu.open,false);assert.ok(h.d.querySelector('.cm-source-mode'));});

test('a later internal autosave overwrites an external version without a conflict',async t=>{const h=await harness(t);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Internal wins'}});h.notes[0].text='External edit';h.notes[0].version='2';h.w.dispatchEvent(new h.w.Event('blur'));await until(()=>h.saved.length===1);assert.equal(h.notes[0].text,'Internal wins');assert.equal(h.view().state.doc.toString(),'Internal wins');assert.equal(h.d.querySelector('#save'),null);assert.equal(h.d.querySelector('#reload'),null);});
test('an external load waits for an in-flight save and then adopts the latest disk text',async t=>{let finish,calls=0,note;const h=await harness(t,{write:async(p,text,saved)=>{calls++;saved.push({path:p,text});await new Promise(r=>finish=r);note.text='External last';note.version='3';return {path:p,text,version:'2'};}});note=h.notes[0];h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Saving draft'}});h.w.dispatchEvent(new h.w.Event('blur'));await until(()=>calls===1);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Pending draft'}});h.changed();await wait(40);finish();await until(()=>h.view().state.doc.toString()==='External last');await wait(700);assert.equal(calls,1);});

