test('rename flushes pending edits, updates links and keeps tabs, draft text and selection',async t=>{const h=await harness(t);h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#title').textContent==='B');h.command('navigate-back');await until(()=>h.d.querySelector('#title').textContent==='A');await until(()=>!h.d.querySelector('#rename-note').disabled);h.view().dispatch({changes:{from:0,to:0,insert:'Draft '},selection:{anchor:3}});h.command('rename');h.d.querySelector('#organize-name').value='Renamed';const form=h.d.querySelector('#organize-form');form.dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('#organize-submit').textContent==='Apply change');assert.ok(h.saved.some(n=>n.path==='A.md'&&n.text.startsWith('Draft ')));form.dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('#title').textContent==='Renamed');assert.ok(h.view().state.doc.toString().startsWith('Draft '));assert.equal(h.view().state.selection.main.head,3);assert.ok(h.notes.find(n=>n.path==='B.md').text.includes('[[/Renamed]]'));assert.equal(h.d.querySelectorAll('#tabs .tab').length,1);await until(()=>h.workspaces.some(w=>w.active==='Renamed.md'));});
test('folder creation shows an empty folder and explorer context supports folder rename',async t=>{const h=await harness(t);h.d.querySelector('#new-folder').click();h.d.querySelector('#organize-name').value='Ideas';h.d.querySelector('#organize-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('.folder[data-path="Ideas"]'));const summary=h.d.querySelector('.folder summary');summary.dispatchEvent(new h.w.MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:50,clientY:120}));assert.equal(h.d.querySelector('#file-context').hidden,false);h.d.querySelector('#context-rename').click();assert.equal(h.d.querySelector('#organize-name').value,'Ideas');});
