test('a failed draft save prevents rename and leaves the original tab editable',async t=>{const h=await harness(t,{write:async()=>{throw new Error('Disk unavailable');}});h.view().dispatch({changes:{from:0,to:0,insert:'Keep draft '}});h.command('rename');h.d.querySelector('#organize-name').value='New';h.d.querySelector('#organize-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('#organize-status').textContent.includes('Disk unavailable'));assert.equal(h.d.querySelector('#title').textContent,'A');assert.ok(h.view().state.doc.toString().startsWith('Keep draft'));h.view().dispatch({changes:{from:0,to:0,insert:'Still editable '}});assert.ok(h.view().state.doc.toString().startsWith('Still editable'));assert.equal(h.notes.some(n=>n.path==='New.md'),false);});
test('workspace restores preferences and the palette keeps disabled note actions from running',async t=>{const h=await harness(t,{restore:{tabs:['A.md'],active:'A.md',preferences:{lineNumbers:true,fontSize:18,theme:'light',pinnedCommands:['rename']}}});assert.ok(h.d.querySelector('.cm-lineNumbers'));assert.equal(h.d.documentElement.dataset.theme,'light');h.command('close-tab');await until(()=>h.d.querySelectorAll('#tabs .tab').length===0);h.command('palette');const q=h.d.querySelector('#command-query');q.value='Rename current';q.dispatchEvent(new h.w.Event('input'));assert.equal(h.d.querySelector('#command-results button').disabled,true);q.dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));assert.equal(h.d.querySelector('#organize-dialog').open,false);});

async function actionHarness(t,options={}){let notes,groups=options.groups?structuredClone(options.groups):[];const calls=[],api={actionList:async p=>structuredClone(groups.filter(g=>g.origin===p)),actionApply:async(id,index,expected)=>{calls.push({kind:'apply',id,index});const batch=groups.find(g=>g.id===id),c=batch.changes[index];if(c.status!=='pending')throw new Error('Already resolved');if(c.action==='edit'){const n=notes.find(n=>n.path===c.path);if(expected!==c.before||n.text!==c.before)throw new Error('The note changed on disk since this proposal.');n.text=c.content;n.version=String(Number(n.version)+1);}else{if(notes.some(n=>n.path===c.path))throw new Error('Already exists');notes.push({path:c.path,title:c.path.split('/').pop().slice(0,-3),text:c.content,version:'1'});}c.status='applied';return {batch:structuredClone(batch),note:{...notes.find(n=>n.path===c.path)},action:c.action};},actionReject:async(id,index)=>{const batch=groups.find(g=>g.id===id);batch.changes[index].status='rejected';return {batch:structuredClone(batch)};},actionUndo:async(id,index,expected)=>{calls.push({kind:'undo',id,index});const batch=groups.find(g=>g.id===id),c=batch.changes[index],n=notes.find(n=>n.path===c.path);if(expected!==c.content||n.text!==c.content)throw new Error('Changed after action');let note;if(c.action==='edit'){n.text=c.before;n.version=String(Number(n.version)+1);note={...n};}else notes.splice(notes.indexOf(n),1);c.status='undone';return {batch:structuredClone(batch),note,action:c.action,path:c.path};}};
 const ai=aiMock({chat:async request=>{ai.requests.push(request);const context=request.context.map(n=>({path:n.path,text:n.text===undefined?notes.find(x=>x.path===n.path).text:n.text}));const spec=options.generate?options.generate(context):[{action:'edit',path:'A.md',content:'AI revised note',reason:'Clearer'}];const proposal={id:'proposal-'+groups.length,summary:'Improve the selected notes',createdAt:Date.now(),provider:'Test Gateway',origin:context[0].path,prompt:request.prompt,context,changes:spec.map(c=>({...c,before:c.action==='edit'?context.find(n=>n.path===c.path).text:'',status:'pending'}))};groups.push(proposal);return {content:'Proposal ready',thread:[...request.history,{role:'user',content:request.prompt},{role:'assistant',content:'Proposal ready'}],proposal:structuredClone(proposal)};}});
 const h=await harness(t,{...options,ai,actions:api});notes=h.notes;await until(()=>!h.d.querySelector('#chat-send').disabled);return {...h,ai,calls,groups:()=>groups};}
async function propose(h,prompt='Improve this note'){h.d.querySelector('#chat-mode').value='actions';h.d.querySelector('#chat-mode').dispatchEvent(new h.w.Event('change'));h.d.querySelector('#chat-input').value=prompt;h.d.querySelector('#chat-send').click();await until(()=>h.d.querySelector('.action-card button'));h.d.querySelector('.action-card button').click();await until(()=>h.d.querySelector('#action-dialog').open);}
test('AI proposals show a literal diff and do not write until accepted; editor undo restores the previous text',async t=>{const h=await actionHarness(t,{text:'Original note',generate:()=>[{action:'edit',path:'A.md',content:'Original note\n\nAI addition <script>window.hacked=true</script>',reason:'Add explanation'}]});await propose(h);assert.equal(h.ai.requests[0].mode,'actions');assert.equal(h.notes[0].text,'Original note');assert.equal(h.saved.length,0);h.d.querySelector('#action-view-diff').click();assert.ok([...h.d.querySelectorAll('.diff-row.add')].some(n=>n.textContent.includes('AI addition')));assert.equal(h.d.querySelectorAll('#action-diff script').length,0);assert.equal(h.w.hacked,undefined);h.d.querySelector('#action-accept').click();await until(()=>h.d.querySelector('#action-status').textContent==='Applied to file');assert.ok(h.view().state.doc.toString().includes('AI addition'));assert.equal(h.calls[0].kind,'apply');h.d.querySelector('#action-close').click();h.d.querySelector('.cm-content').dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}));assert.equal(h.view().state.doc.toString(),'Original note');});
test('AI proposal edits use unsaved context, apply per note and reject another without writing it',async t=>{const h=await actionHarness(t,{text:'Original',generate:()=>[{action:'edit',path:'A.md',content:'Updated A',reason:'A'},{action:'edit',path:'B.md',content:'Updated B',reason:'B'}]});h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Unsaved draft'}});await propose(h,'Improve @[[B.md]]');assert.equal(h.groups()[0].changes[0].before,'Unsaved draft');assert.match(h.d.querySelector('#action-context').textContent,/A.md.*B.md/);h.d.querySelector('#action-accept').click();await until(()=>h.groups()[0].changes[0].status==='applied');assert.ok(h.saved.some(n=>n.text==='Unsaved draft'));h.d.querySelectorAll('#action-files button')[1].click();h.d.querySelector('#action-reject').click();await until(()=>h.d.querySelector('#action-status').textContent==='Rejected');assert.equal(h.notes.find(n=>n.path==='B.md').text,'# B\n[[A]]');assert.equal(h.view().state.doc.toString(),'Updated A');});
test('AI action review refuses a changed editor and offers a revised request without overwriting it',async t=>{const h=await actionHarness(t,{text:'Original'});await propose(h);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'Later typing'}});h.d.querySelector('#action-accept').click();await until(()=>h.d.querySelector('#action-error').textContent.includes('changed'));assert.equal(h.calls.length,0);assert.equal(h.view().state.doc.toString(),'Later typing');h.d.querySelector('#action-revise').click();assert.equal(h.d.querySelector('#action-dialog').open,false);assert.equal(h.d.querySelector('#chat-mode').value,'actions');assert.ok(h.d.querySelector('#chat-input').value.includes('Improve this note'));});
test('AI creation opens a new note and Undo this action closes it while preserving the originating note',async t=>{const h=await actionHarness(t,{text:'Original',generate:()=>[{action:'create',path:'Summary.md',content:'# Summary\n\nNew content',reason:'Summary'}]});await propose(h);h.d.querySelector('#action-accept').click();await until(()=>h.d.querySelector('#title').textContent==='Summary');await until(()=>h.d.querySelector('#action-status').textContent==='Applied to file');assert.equal(h.notes.find(n=>n.path==='Summary.md').text,'# Summary\n\nNew content');h.d.querySelector('#action-undo').click();await until(()=>h.d.querySelector('#action-status').textContent==='Undone');assert.equal(h.notes.some(n=>n.path==='Summary.md'),false);assert.equal(h.d.querySelector('#title').textContent,'A');assert.equal(h.view().state.doc.toString(),'Original');});
test('AI review restores persisted proposals and can undo a prior edit after reopening the app',async t=>{const batch={id:'prior',summary:'Earlier change',provider:'Gateway',createdAt:1,origin:'A.md',prompt:'Improve',context:[{path:'A.md',text:'Original'}],changes:[{action:'edit',path:'A.md',before:'Original',content:'Already applied',reason:'Earlier edit',status:'applied'}]};const h=await actionHarness(t,{text:'Already applied',groups:[batch]});await until(()=>h.d.querySelector('.action-card button'));h.command('ai-review');await until(()=>h.d.querySelector('#action-dialog').open);h.d.querySelector('#action-undo').click();await until(()=>h.d.querySelector('#action-status').textContent==='Undone');assert.equal(h.view().state.doc.toString(),'Original');});
test('an AI proposal stays with its originating note when generation finishes on another tab',async t=>{const h=await actionHarness(t,{text:'Original'});let finish;const original=h.ai.chat;h.ai.chat=request=>new Promise(resolve=>{finish=()=>original(request).then(resolve);});h.d.querySelector('#chat-mode').value='actions';h.d.querySelector('#chat-mode').dispatchEvent(new h.w.Event('change'));h.d.querySelector('#chat-input').value='Improve';h.d.querySelector('#chat-send').click();await until(()=>finish);h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#chat-note').textContent==='B.md');finish();await until(()=>h.d.querySelector('#chat-send').disabled===false);assert.equal(h.d.querySelector('.action-card'),null);h.command('navigate-back');await until(()=>h.d.querySelector('.action-card'));assert.equal(h.d.querySelector('#chat-note').textContent,'A.md');});

test('empty AI proposals show the explanation without accept or reject controls',async t=>{const h=await actionHarness(t,{text:'Original',generate:()=>[]});await propose(h);assert.equal(h.d.querySelector('#action-empty').hidden,false);assert.equal(h.d.querySelector('#action-accept').hidden,true);assert.equal(h.d.querySelector('#action-reject').hidden,true);assert.equal(h.calls.length,0);assert.equal(h.view().state.doc.toString(),'Original');});
test('AI can apply a mentioned unopened note while preserving the active note and its selection',async t=>{const h=await actionHarness(t,{text:'Current note',generate:()=>[{action:'edit',path:'B.md',content:'Mentioned note improved',reason:'Improve B'}]});h.view().dispatch({selection:{anchor:4}});await propose(h,'Improve @[[B.md]]');h.d.querySelector('#action-accept').click();await until(()=>h.d.querySelector('#action-status').textContent==='Applied to file');assert.equal(h.notes.find(n=>n.path==='B.md').text,'Mentioned note improved');assert.equal(h.d.querySelector('#title').textContent,'A');assert.equal(h.view().state.doc.toString(),'Current note');assert.equal(h.view().state.selection.main.head,4);});

function diagramMock(){const canvases=[];return {canvases,renderMermaid:async source=>{if(source.includes('broken['))throw new Error('Invalid Mermaid syntax');return '<svg xmlns="http://www.w3.org/2000/svg"><text>'+source.replaceAll('&','&amp;').replaceAll('<','&lt;')+'</text></svg>';},drawingSvg:async scene=>{const h=new JSDOM('<svg xmlns="http://www.w3.org/2000/svg"><text>'+scene.elements.length+' shapes</text></svg>');return h.window.document.querySelector('svg');},mountDrawing:(host,scene,options)=>{const session={scene,options,host,destroyed:false,updates:[],replace:next=>{session.scene=next;session.updates.push(next);},setReadonly:value=>session.readonly=value,destroy:()=>{session.destroyed=true;host.replaceChildren();}};const button=host.ownerDocument.createElement('button');button.textContent='Add test shape';button.onclick=()=>{session.scene={...session.scene,elements:[...session.scene.elements,{id:'shape-'+session.scene.elements.length,type:'rectangle',x:0,y:0,width:100,height:50}]};options.onChange(session.scene);};host.append(button);canvases.push(session);return session;}};}
const emptyScene=()=>require('../core/drawings.cjs').emptyDrawing();
test('Mermaid renders in live and reading views, edits source with autosave and retains ordinary code blocks',async t=>{const diagrams=diagramMock(),source='flowchart TD\n A --> B',text='# Before\n\n```mermaid\n'+source+'\n```\n\n```js\nconst x = 1;\n```\n\nAfter';const h=await harness(t,{text,diagrams});await until(()=>h.d.querySelector('.mermaid-block svg'));h.d.querySelector('.mermaid-block button').click();assert.equal(h.d.querySelector('#mermaid-dialog').open,true);const input=h.d.querySelector('#mermaid-source');input.value='flowchart TD\n A --> C';input.dispatchEvent(new h.w.Event('input'));await until(()=>h.saved.length);assert.ok(h.notes[0].text.includes('A --> C'));assert.ok(h.notes[0].text.includes('```js\nconst x = 1;'));assert.ok(h.notes[0].text.endsWith('After'));h.d.querySelector('#mermaid-close').click();h.d.querySelector('#preview-button').click();await until(()=>h.d.querySelector('#reading .mermaid-block svg'));assert.equal(h.d.querySelector('#reading code.language-js').textContent.trim(),'const x = 1;');h.d.querySelector('#reading .mermaid-block button').click();assert.equal(h.d.querySelector('#mermaid-source').value,'flowchart TD\n A --> C');});
test('invalid Mermaid source remains editable and autosaves without executing HTML',async t=>{const h=await harness(t,{text:'# Note\n\n```mermaid\nflowchart TD\n A --> B\n```',diagrams:diagramMock()});await until(()=>h.d.querySelector('.mermaid-block svg'));h.d.querySelector('.mermaid-block button').click();const input=h.d.querySelector('#mermaid-source');input.value='broken[ <script>window.hacked=true</script>';input.dispatchEvent(new h.w.Event('input'));await until(()=>h.d.querySelector('#mermaid-live-preview .diagram-error'));assert.equal(h.w.hacked,undefined);await until(()=>h.saved.length);assert.ok(h.notes[0].text.includes('broken['));input.value='flowchart TD\n C --> D';input.dispatchEvent(new h.w.Event('input'));await until(()=>h.d.querySelector('#mermaid-live-preview svg'));});
test('native drawing tabs open the canvas without rewriting the file and external loads refresh the mounted scene',async t=>{const diagrams=diagramMock(),h=await harness(t,{diagrams,extraNotes:[{path:'Sketch.excalidraw',title:'Sketch',text:emptyScene(),version:'1'}]});[...h.d.querySelectorAll('#files button')].find(b=>b.dataset.path==='Sketch.excalidraw').click();await until(()=>h.d.querySelector('#drawing-editor .drawing-canvas'));await until(()=>diagrams.canvases.length);assert.equal(h.d.querySelector('#editor').hidden,true);assert.equal(h.saved.length,0);const drawing=h.notes.find(n=>n.path==='Sketch.excalidraw'),next=JSON.parse(emptyScene());next.elements=[{id:'external',type:'rectangle',x:0,y:0,width:40,height:40}];drawing.text=JSON.stringify(next);drawing.version='2';h.changed();await until(()=>diagrams.canvases[0].updates.length);assert.equal(diagrams.canvases[0].updates.at(-1).elements[0].id,'external');assert.equal(h.saved.length,0);assert.ok(h.workspaces.some(w=>w.tabs.includes('Sketch.excalidraw')));});
test('inline drawing edits save the drawing file, preserve the note and survive polling',async t=>{const diagrams=diagramMock(),text='# Note\n\n![[Sketch.excalidraw|600]]\n\nAfter',h=await harness(t,{text,diagrams,extraNotes:[{path:'Sketch.excalidraw',title:'Sketch',text:emptyScene(),version:'1'}]});await until(()=>h.d.querySelector('.drawing-block'));[...h.d.querySelectorAll('.drawing-block button')].find(b=>b.textContent==='Edit inline').click();await until(()=>h.d.querySelector('.drawing-canvas button'));h.d.querySelector('.drawing-canvas button').click();await until(()=>h.saved.some(n=>n.path==='Sketch.excalidraw'));assert.equal(h.notes[0].text,text);assert.equal(h.d.querySelector('#title').textContent,'A');assert.equal(JSON.parse(h.notes.find(n=>n.path==='Sketch.excalidraw').text).elements.length,1);await wait(1600);assert.ok(h.d.querySelector('.drawing-canvas'));assert.equal(diagrams.canvases[0].destroyed,false);const drawingTab=[...h.d.querySelectorAll('#tabs .tab')].find(n=>n.querySelector('.tab-name').title==='Sketch.excalidraw');drawingTab.querySelector('button:last-child').click();await until(()=>h.d.querySelector('.drawing-preview svg'));assert.equal(diagrams.canvases[0].destroyed,true);[...h.d.querySelectorAll('.drawing-block button')].find(b=>b.textContent==='Edit inline').click();await until(()=>diagrams.canvases.length===2);h.d.querySelector('.drawing-canvas button').click();await until(()=>JSON.parse(h.notes.find(n=>n.path==='Sketch.excalidraw').text).elements.length===2);});
test('reading view supports inline drawing edits and creation embeds into the current Markdown note',async t=>{const diagrams=diagramMock(),h=await harness(t,{text:'# Note\n\n![[Sketch.excalidraw]]',diagrams,extraNotes:[{path:'Sketch.excalidraw',title:'Sketch',text:emptyScene(),version:'1'}]});h.d.querySelector('#preview-button').click();await until(()=>h.d.querySelector('#reading .drawing-block'));[...h.d.querySelectorAll('#reading .drawing-block button')].find(b=>b.textContent==='Edit inline').click();await until(()=>h.d.querySelector('#reading .drawing-canvas button'));h.d.querySelector('#reading .drawing-canvas button').click();await until(()=>h.saved.length);await wait(1600);assert.ok(h.d.querySelector('#reading .drawing-canvas'));[...h.d.querySelectorAll('#reading .drawing-block button')].find(b=>b.textContent==='Done').click();h.w.vaultAPI.createDrawing=async path=>h.notes.push({path,title:'New',text:emptyScene(),version:'1'});h.command('embed-drawing');h.d.querySelector('#drawing-new-name').value='Drawings/New.excalidraw';h.d.querySelector('#drawing-new-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>!h.d.querySelector('#drawing-new-dialog').open);await until(()=>h.saved.some(n=>n.path==='A.md'&&n.text.includes('![[/Drawings/New.excalidraw]]')));assert.equal(h.d.querySelector('#title').textContent,'A');});
test('Markdown Excalidraw scenes edit through the canvas while keeping prose, frontmatter and text index',async t=>{const diagrams=diagramMock(),original='---\nexcalidraw-plugin: parsed\ntags: [work]\n---\nKeep my prose.\n\n## Text Elements\n\n%%\n## Drawing\n```json\n'+emptyScene().trim()+'\n```\n%%\n',h=await harness(t,{diagrams,extraNotes:[{path:'Sketch.excalidraw.md',title:'Sketch',text:original,version:'1'}]});[...h.d.querySelectorAll('#files button')].find(b=>b.dataset.path==='Sketch.excalidraw.md').click();await until(()=>h.d.querySelector('#drawing-editor .drawing-canvas button'));h.d.querySelector('#drawing-editor .drawing-canvas button').click();await until(()=>h.saved.length);const text=h.notes.find(n=>n.path==='Sketch.excalidraw.md').text;assert.ok(text.includes('tags: [work]'));assert.ok(text.includes('Keep my prose.'));assert.ok(text.includes('%%\n## Drawing'));assert.equal(require('../core/drawings.cjs').parseDrawing(text,'Sketch.excalidraw.md').scene.elements.length,1);});

test('property editor edits typed YAML with autosave, preserves body and uses editor undo',async t=>{const original='---\n# keep\nstatus: Draft\npriority: 2\ndone: false\ntags: [work]\n---\n# Body\n\nKeep my prose.',h=await harness(t,{text:original});const input=h.d.querySelector('.property-row[data-key="status"] [data-part="value"]');assert.equal(input.disabled,false);assert.equal(input.value,'Draft');input.value='Ready';input.dispatchEvent(new h.w.Event('input'));await until(()=>h.saved.length);assert.match(h.notes[0].text,/status: Ready/);assert.ok(h.notes[0].text.includes('# keep'));assert.ok(h.notes[0].text.endsWith('Keep my prose.'));h.d.querySelector('[aria-label="status"]').dispatchEvent(new h.w.KeyboardEvent('keydown',{key:'z',code:'KeyZ',ctrlKey:true,bubbles:true}));assert.equal(h.view().state.doc.toString(),original);});
test('property addition supports numbers, remembers types and refuses stale note dialogs',async t=>{const h=await harness(t,{text:'# Body'});h.command('add-property');h.d.querySelector('#property-new-name').value='priority';h.d.querySelector('#property-new-type').value='number';h.d.querySelector('#property-new-value').value='4';h.d.querySelector('#property-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>h.d.querySelector('.property-row[data-key="priority"]'));assert.equal(h.d.querySelector('[aria-label="priority"]').type,'number');assert.equal(require('../core/metadata.cjs').readMetadata(h.view().state.doc.toString()).values.priority,4);await until(()=>h.workspaces.some(w=>w.preferences.propertyTypes.priority==='number'));h.command('add-property');h.d.querySelector('#property-new-name').value='stale';h.d.querySelectorAll('#files button')[1].click();await until(()=>h.d.querySelector('#title').textContent==='B');h.d.querySelector('#property-form').dispatchEvent(new h.w.Event('submit',{bubbles:true,cancelable:true}));assert.match(h.d.querySelector('#property-create-error').textContent,/active note changed/);assert.ok(!h.view().state.doc.toString().includes('stale:'));});
test('external YAML loads refresh focused properties without writing stale field values',async t=>{const h=await harness(t,{text:'---\nstatus: Draft\n---\nBody'});h.d.querySelector('[aria-label="status"]').focus();h.notes[0].text='---\nstatus: External\n---\nBody';h.notes[0].version='2';h.changed();await until(()=>h.d.querySelector('[aria-label="status"]').value==='External');assert.equal(h.d.activeElement.getAttribute('aria-label'),'status');assert.equal(h.saved.length,0);const input=h.d.querySelector('[aria-label="status"]');input.value='Latest';input.dispatchEvent(new h.w.Event('input'));await until(()=>h.saved.length);assert.match(h.notes[0].text,/status: Latest/);});
test('nested tag browsing filters notes and search finds unsaved drafts immediately',async t=>{const h=await harness(t,{text:'#work/topic\nOriginal'});h.command('tags');await until(()=>h.d.querySelector('#tag-browser .tag-item'));const parent=h.d.querySelector('#tag-browser summary button');assert.match(parent.textContent,/#work1/);parent.click();await until(()=>h.d.querySelectorAll('#files button').length===1);assert.equal(h.d.querySelector('#search').value,'tag:#work');assert.equal(h.d.querySelector('#files button').dataset.path,'A.md');h.view().dispatch({changes:{from:h.view().state.doc.length,insert:'\nUnsaved surprise'}});const search=h.d.querySelector('#search');search.value='surprise';search.dispatchEvent(new h.w.Event('input'));await until(()=>h.d.querySelector('.search-snippet')?.textContent.includes('surprise'));assert.equal(h.saved.length,0);h.d.querySelector('#save-search').click();await until(()=>h.workspaces.some(w=>w.preferences.savedSearches.includes('surprise')));search.value='unknown:foo';search.dispatchEvent(new h.w.Event('input'));await until(()=>h.d.querySelector('#search-error').textContent.includes('Unknown'));assert.equal(h.d.querySelectorAll('#files button').length,0);});
test('properties hide in source mode, remain visible in reading view and malformed YAML is retained',async t=>{const h=await harness(t,{text:'---\nstatus: Draft\n---\n# Body'});assert.equal(h.d.querySelector('#properties').hidden,false);h.d.querySelector('#preview-button').click();await until(()=>h.d.querySelector('#reading h1'));assert.equal(h.d.querySelector('#reading h1').textContent,'Body');assert.ok(!h.d.querySelector('#reading').textContent.includes('status:'));h.command('source-mode');assert.equal(h.d.querySelector('#properties').hidden,true);h.command('source-mode');assert.equal(h.d.querySelector('#properties').hidden,false);h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'---\nstatus: [bad\n---\nBody'}});assert.match(h.d.querySelector('#property-error').textContent,/YAML/);assert.equal(h.d.querySelector('#property-add').disabled,true);assert.ok(h.view().state.doc.toString().includes('status: [bad'));});
test('changing a property type uses its latest edited value rather than its original value',async t=>{const h=await harness(t,{text:'---\nstatus: Draft\n---\nBody'});const value=h.d.querySelector('[aria-label="status"]');value.value='Ready';value.dispatchEvent(new h.w.Event('input'));const type=h.d.querySelector('[aria-label="Type of status"]');type.value='list';type.dispatchEvent(new h.w.Event('change'));assert.deepEqual(require('../core/metadata.cjs').readMetadata(h.view().state.doc.toString()).values.status,['Ready']);assert.equal(h.d.querySelector('[aria-label="status"]').tagName,'TEXTAREA');});
test('external values that conflict with a registered type remain visible and cannot be overwritten by an empty number input',async t=>{const h=await harness(t,{text:'---\npriority: high\n---\nBody',restore:{tabs:['A.md'],active:'A.md',preferences:{propertyTypes:{priority:'number'}}}});const input=h.d.querySelector('[aria-label="priority"]');assert.equal(input.value,'high');assert.equal(input.disabled,true);const type=h.d.querySelector('[aria-label="Type of priority"]');assert.equal(type.disabled,false);type.value='text';type.dispatchEvent(new h.w.Event('change'));assert.equal(h.d.querySelector('[aria-label="priority"]').value,'high');assert.equal(h.d.querySelector('[aria-label="priority"]').disabled,false);});
