test('autosave timestamps preserve concurrent typing, caret position and clean state without a feedback loop',async t=>{const {stampNote}=require('../core/note-timestamps.cjs'),{frontmatter}=require('../core/metadata.cjs');let finish,calls=0,h;h=await harness(t,{text:'Original',write:async(p,text,saved)=>{calls++;if(calls===1)await new Promise(r=>finish=r);const note=h.notes.find(n=>n.path===p),result=stampNote(p,text,{old:note.text,createdAt:Date.parse('2020-01-01T00:00:00Z')});note.text=result.text;note.version=String(Number(note.version)+1);saved.push({path:p,text:result.text});return {...note};}});h.view().dispatch({changes:{from:0,to:h.view().state.doc.length,insert:'First'},selection:{anchor:5}});await until(()=>finish);h.view().dispatch({changes:{from:0,to:5,insert:'Second'},selection:{anchor:6}});finish();await until(()=>calls===2&&h.d.querySelectorAll('.dirty-mark').length===0);const current=h.view().state.doc.toString();assert.equal(frontmatter(current).body,'Second');assert.equal(h.view().state.selection.main.head,frontmatter(current).end+6);assert.equal(current,h.saved.at(-1).text);await wait(900);assert.equal(calls,2);assert.equal(frontmatter(h.saved[0].text).body,'First');});

